CREATE TABLE lowpoly_mesh_state (id INTEGER PRIMARY KEY REFERENCES lowpoly_object(id));
CREATE TABLE lowpoly_mesh_vertex (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES lowpoly_mesh_state(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), position_x REAL, position_y REAL, position_z REAL, normal_x REAL, normal_y REAL, normal_z REAL, halfedge_index INTEGER CHECK(halfedge_index BETWEEN 0 AND 4294967295), position_x_ieee754_bits INTEGER NOT NULL CHECK(position_x_ieee754_bits BETWEEN 0 AND 4294967295), position_x_numeric_class TEXT NOT NULL, position_y_ieee754_bits INTEGER NOT NULL CHECK(position_y_ieee754_bits BETWEEN 0 AND 4294967295), position_y_numeric_class TEXT NOT NULL, position_z_ieee754_bits INTEGER NOT NULL CHECK(position_z_ieee754_bits BETWEEN 0 AND 4294967295), position_z_numeric_class TEXT NOT NULL, normal_x_ieee754_bits INTEGER CHECK(normal_x_ieee754_bits BETWEEN 0 AND 4294967295), normal_x_numeric_class TEXT, normal_y_ieee754_bits INTEGER CHECK(normal_y_ieee754_bits BETWEEN 0 AND 4294967295), normal_y_numeric_class TEXT, normal_z_ieee754_bits INTEGER CHECK(normal_z_ieee754_bits BETWEEN 0 AND 4294967295), normal_z_numeric_class TEXT);
CREATE TABLE lowpoly_mesh_halfedge (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES lowpoly_mesh_state(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), vertex_index INTEGER NOT NULL CHECK(vertex_index BETWEEN 0 AND 4294967295), twin_index INTEGER CHECK(twin_index BETWEEN 0 AND 4294967295), next_index INTEGER NOT NULL CHECK(next_index BETWEEN 0 AND 4294967295), face_index INTEGER CHECK(face_index BETWEEN 0 AND 4294967295), uv_u REAL, uv_v REAL, uv_u_ieee754_bits INTEGER NOT NULL CHECK(uv_u_ieee754_bits BETWEEN 0 AND 4294967295), uv_u_numeric_class TEXT NOT NULL, uv_v_ieee754_bits INTEGER NOT NULL CHECK(uv_v_ieee754_bits BETWEEN 0 AND 4294967295), uv_v_numeric_class TEXT NOT NULL);
CREATE TABLE lowpoly_mesh_face (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES lowpoly_mesh_state(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), halfedge_index INTEGER NOT NULL CHECK(halfedge_index BETWEEN 0 AND 4294967295), smooth INTEGER NOT NULL CHECK(smooth IN(0,1)), flipped INTEGER NOT NULL CHECK(flipped IN(0,1)));
CREATE TABLE lowpoly_mesh_seam (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES lowpoly_mesh_state(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), halfedge_index INTEGER NOT NULL CHECK(halfedge_index BETWEEN 0 AND 4294967295));
CREATE TABLE lowpoly_mesh_attribute (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES lowpoly_mesh_state(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, domain TEXT NOT NULL CHECK(domain IN('vertex','corner','face','edge')), semantic TEXT NOT NULL CHECK(semantic IN('normal','uv','color','material','custom')), interpolation TEXT NOT NULL CHECK(interpolation IN('linear','nearest','constant')), has_indices INTEGER NOT NULL CHECK(has_indices IN(0,1)));
CREATE TABLE lowpoly_mesh_attribute_index (id INTEGER PRIMARY KEY, attribute_id INTEGER NOT NULL REFERENCES lowpoly_mesh_attribute(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 4294967295));
CREATE TABLE lowpoly_mesh_attribute_sample (id INTEGER PRIMARY KEY, attribute_id INTEGER NOT NULL REFERENCES lowpoly_mesh_attribute(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value_id INTEGER NOT NULL REFERENCES lowpoly_mesh_value(id));
CREATE TABLE lowpoly_mesh_material (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES lowpoly_mesh_state(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES lowpoly_mesh_value(id));
CREATE TABLE lowpoly_mesh_texture (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES lowpoly_mesh_state(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, mime TEXT NOT NULL);
CREATE TABLE lowpoly_mesh_texture_octet (id INTEGER PRIMARY KEY, texture_id INTEGER NOT NULL REFERENCES lowpoly_mesh_texture(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255));
CREATE TABLE lowpoly_mesh_value (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN('null','boolean','unsigned','signed','float','text','bytes','array','object')));
CREATE TABLE lowpoly_mesh_boolean (id INTEGER PRIMARY KEY REFERENCES lowpoly_mesh_value(id), value INTEGER NOT NULL CHECK(value IN(0,1)));
CREATE TABLE lowpoly_mesh_unsigned (id INTEGER PRIMARY KEY REFERENCES lowpoly_mesh_value(id), value TEXT NOT NULL CHECK(length(value) BETWEEN 1 AND 20 AND value NOT GLOB '*[^0-9]*' AND (value='0' OR substr(value,1,1) BETWEEN '1' AND '9') AND (length(value)<20 OR value<='18446744073709551615')));
CREATE TABLE lowpoly_mesh_signed (id INTEGER PRIMARY KEY REFERENCES lowpoly_mesh_value(id), value INTEGER NOT NULL);
CREATE TABLE lowpoly_mesh_float (id INTEGER PRIMARY KEY REFERENCES lowpoly_mesh_value(id), value REAL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL);
CREATE TABLE lowpoly_mesh_text (id INTEGER PRIMARY KEY REFERENCES lowpoly_mesh_value(id), value TEXT NOT NULL);
CREATE TABLE lowpoly_mesh_bytes (id INTEGER PRIMARY KEY REFERENCES lowpoly_mesh_value(id));
CREATE TABLE lowpoly_mesh_bytes_octet (id INTEGER PRIMARY KEY, bytes_id INTEGER NOT NULL REFERENCES lowpoly_mesh_bytes(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255));
CREATE TABLE lowpoly_mesh_array_member (id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL REFERENCES lowpoly_mesh_value(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value_id INTEGER NOT NULL REFERENCES lowpoly_mesh_value(id));
CREATE TABLE lowpoly_mesh_object_member (id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL REFERENCES lowpoly_mesh_value(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES lowpoly_mesh_value(id));
